const KIND_WORD = { income: 'Pay', 'maybe-in': 'Maybe in', bill: 'Bill', paylater: 'Pay later', transfer: 'Transfer', 'transfer-in': 'Transfer in', 'to-goals': 'To goals', 'card-payment': 'Card payment', 'loan-payment': 'Loan payment', interest: 'Interest', 'late-fee': 'Late fee', statement: 'Statement', shortfall: 'Could not pay', everyday: 'Everyday', log: 'Logged', 'auto-cover': 'Topped up', sweep: 'Sweep' };

